void fuzz_get_chunk(sc_reader_t *reader, const uint8_t **chunk, uint16_t *chunk_size)
{
    struct driver_data *data;
    if (chunk) *chunk = NULL;
    if (chunk_size) *chunk_size = 0;
    if (!chunk || !chunk_size || !reader) return;
    data = reader->drv_data;
    if (!data || !data->Data || data->Size < sizeof *chunk_size) return;
    data->Size -= sizeof *chunk_size;
